"""Auto-generated file content kept as revisions, run against a real database."""

from __future__ import annotations

import uuid
from collections.abc import AsyncGenerator

import pytest
import sqlalchemy as sa

from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID
from ai.backend.common.data.entity.domain import DomainID
from ai.backend.common.data.entity.user import UserEntityType, UserID
from ai.backend.common.types import ResourceSlot
from ai.backend.manager.data.auto_generated_file.types import AutoGeneratedFileRevisionSpec
from ai.backend.manager.data.dotfile.types import DotfileEntry
from ai.backend.manager.errors.storage import DotfileNotFound
from ai.backend.manager.models.auto_generated_file.creators import AutoGeneratedFileCreator
from ai.backend.manager.models.auto_generated_file.row import AutoGeneratedFileRow
from ai.backend.manager.models.auto_generated_file.updaters import AutoGeneratedFileUpdater
from ai.backend.manager.models.auto_generated_file_revision.row import AutoGeneratedFileRevisionRow
from ai.backend.manager.models.domain.row import DomainRow
from ai.backend.manager.models.resource_policy.row import UserResourcePolicyRow
from ai.backend.manager.models.user.row import UserRole, UserRow, UserStatus
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.manager.models.virtual_entity.entity_membership import EntityMembershipRow
from ai.backend.manager.models.virtual_entity.entity_membership_cap import (
    EntityMembershipCapRow,
)
from ai.backend.manager.models.virtual_entity.entity_membership_field import (
    EntityMembershipFieldRow,
)
from ai.backend.manager.models.virtual_entity.scope_binding import ScopeBindingRow
from ai.backend.manager.models.virtual_entity.virtual_entity import VirtualEntityRow
from ai.backend.manager.repositories.auto_generated_file.repository import (
    AutoGeneratedFileRepository,
)
from ai.backend.manager.repositories.ops.v2.provider import V2DBOpsProvider
from ai.backend.testutils.db import with_tables

_ENTRY = DotfileEntry(path=".bashrc", perm="644", data="export A=1\n")


class TestAutoGeneratedFileRevision:
    @pytest.fixture
    async def db(
        self, database_connection: ExtendedAsyncSAEngine
    ) -> AsyncGenerator[ExtendedAsyncSAEngine]:
        async with with_tables(
            database_connection,
            [
                DomainRow,
                UserResourcePolicyRow,
                UserRow,
                VirtualEntityRow,
                EntityMembershipRow,
                EntityMembershipCapRow,
                EntityMembershipFieldRow,
                ScopeBindingRow,
                AutoGeneratedFileRow,
                AutoGeneratedFileRevisionRow,
            ],
        ):
            yield database_connection

    @pytest.fixture
    def repository(self, db: ExtendedAsyncSAEngine) -> AutoGeneratedFileRepository:
        return AutoGeneratedFileRepository(V2DBOpsProvider(db))

    @pytest.fixture
    async def user_id(self, db: ExtendedAsyncSAEngine) -> UserID:
        return await self._add_user(db)

    @pytest.fixture
    async def other_user_id(self, db: ExtendedAsyncSAEngine, user_id: UserID) -> UserID:
        return await self._add_user(db)

    @pytest.fixture
    async def created_file_id(
        self, repository: AutoGeneratedFileRepository, user_id: UserID
    ) -> AutoGeneratedFileID:
        created = await repository.create_default(
            AutoGeneratedFileCreator(owner=user_id, entry=_ENTRY), user_id
        )
        return created.id

    async def _add_user(self, db: ExtendedAsyncSAEngine) -> UserID:
        user_id = UserID(uuid.uuid4())
        domain_id = DomainID(uuid.uuid4())
        domain_name = f"domain-{domain_id.hex[:8]}"
        policy_name = f"policy-{user_id.hex[:8]}"
        async with db.begin_session() as session:
            session.add(
                DomainRow(
                    id=domain_id,
                    name=domain_name,
                    description="",
                    is_active=True,
                    total_resource_slots=ResourceSlot(),
                    allowed_vfolder_hosts={},
                    allowed_docker_registries=[],
                    integration_id=None,
                )
            )
            session.add(
                UserResourcePolicyRow(
                    name=policy_name,
                    max_vfolder_count=10,
                    max_quota_scope_size=-1,
                    max_session_count_per_model_session=10,
                    max_customized_image_count=10,
                )
            )
            await session.flush()
            session.add(
                UserRow(
                    uuid=user_id,
                    username=f"user-{user_id.hex[:8]}",
                    email=f"user-{user_id.hex[:8]}@example.com",
                    password=None,
                    need_password_change=False,
                    full_name="",
                    description="",
                    status=UserStatus.ACTIVE,
                    status_info="",
                    domain_name=domain_name,
                    role=UserRole.USER,
                    resource_policy=policy_name,
                    allowed_client_ip=None,
                    totp_key=None,
                    domain_id=domain_id,
                )
            )
            session.add(VirtualEntityRow(entity_type=UserEntityType(), entity_id=user_id))
        return user_id

    async def _revisions(
        self, db: ExtendedAsyncSAEngine, file_id: AutoGeneratedFileID
    ) -> list[tuple[int, str, UserID | None]]:
        async with db.begin_readonly_session() as session:
            rows = await session.execute(
                sa.select(
                    AutoGeneratedFileRevisionRow.revision_number,
                    AutoGeneratedFileRevisionRow.data,
                    AutoGeneratedFileRevisionRow.creator_id,
                )
                .where(AutoGeneratedFileRevisionRow.file_id == file_id)
                .order_by(AutoGeneratedFileRevisionRow.revision_number)
            )
            return [(row.revision_number, row.data, row.creator_id) for row in rows]

    async def _defaults(
        self, db: ExtendedAsyncSAEngine, owner: UserID
    ) -> dict[AutoGeneratedFileID, bool]:
        async with db.begin_readonly_session() as session:
            rows = await session.execute(
                sa.select(AutoGeneratedFileRow.id, AutoGeneratedFileRow.is_default).where(
                    AutoGeneratedFileRow.entity_id == owner
                )
            )
            return {row.id: row.is_default for row in rows}

    async def test_create_writes_the_data_as_revision_1(
        self,
        db: ExtendedAsyncSAEngine,
        user_id: UserID,
        created_file_id: AutoGeneratedFileID,
    ) -> None:
        assert await self._revisions(db, created_file_id) == [(1, _ENTRY.data, user_id)]

    async def test_create_adds_a_file_that_is_not_the_default(
        self,
        db: ExtendedAsyncSAEngine,
        repository: AutoGeneratedFileRepository,
        user_id: UserID,
        created_file_id: AutoGeneratedFileID,
    ) -> None:
        variant = await repository.create(
            AutoGeneratedFileCreator(owner=user_id, entry=_ENTRY), user_id
        )

        assert variant.is_default is False
        assert await self._defaults(db, user_id) == {created_file_id: True, variant.id: False}

    async def test_create_default_takes_the_default_of_its_path(
        self,
        db: ExtendedAsyncSAEngine,
        repository: AutoGeneratedFileRepository,
        user_id: UserID,
        created_file_id: AutoGeneratedFileID,
    ) -> None:
        variant = await repository.create_default(
            AutoGeneratedFileCreator(owner=user_id, entry=_ENTRY), user_id
        )

        assert variant.is_default is True
        assert await self._defaults(db, user_id) == {created_file_id: False, variant.id: True}

    async def test_update_rewrites_perm_and_appends_the_next_revision(
        self,
        db: ExtendedAsyncSAEngine,
        repository: AutoGeneratedFileRepository,
        user_id: UserID,
        other_user_id: UserID,
        created_file_id: AutoGeneratedFileID,
    ) -> None:
        updated = await repository.update(
            AutoGeneratedFileUpdater(auto_generated_file_id=created_file_id, perm="600"),
            AutoGeneratedFileRevisionSpec(data="export A=2\n", creator_id=other_user_id),
        )

        assert updated.perm == "600"
        assert await self._revisions(db, created_file_id) == [
            (1, _ENTRY.data, user_id),
            (2, "export A=2\n", other_user_id),
        ]

    async def test_default_files_carry_the_latest_revision(
        self,
        repository: AutoGeneratedFileRepository,
        user_id: UserID,
        created_file_id: AutoGeneratedFileID,
    ) -> None:
        await repository.update(
            AutoGeneratedFileUpdater(auto_generated_file_id=created_file_id, perm="600"),
            AutoGeneratedFileRevisionSpec(data="export A=2\n", creator_id=user_id),
        )

        defaults = await repository.default_files(user_id)

        assert defaults.entries == (DotfileEntry(_ENTRY.path, "600", "export A=2\n"),)

    async def test_update_of_a_missing_file_writes_no_revision(
        self,
        db: ExtendedAsyncSAEngine,
        repository: AutoGeneratedFileRepository,
        user_id: UserID,
    ) -> None:
        missing = AutoGeneratedFileID(uuid.uuid4())

        with pytest.raises(DotfileNotFound):
            await repository.update(
                AutoGeneratedFileUpdater(auto_generated_file_id=missing, perm="600"),
                AutoGeneratedFileRevisionSpec(data="export A=2\n", creator_id=user_id),
            )

        assert await self._revisions(db, missing) == []
